#!/usr/bin/env bun
// Regenerates docs/content/reference/module-reference.md from the runtime module
// `meta` summaries (the SAME source the `rolecall docs modules` CLI subcommand reads),
// so the reference page never drifts from what the CLI reports. Run with
// `bun run embed:docs` — that script chains to this one. The generated file is
// committed so `bun test`/`bun run build` work without this step first, and it is
// picked up by scripts/embed-docs.ts (it lives under docs/content/reference/),
// which makes it both rendered by VitePress AND indexed by `rolecall docs search`.

import { registerAllModules } from "../src/modules/builtins";
import { searchModules } from "../src/modules/search";
import { fileURLToPath } from "node:url";
import { dirname, join, relative } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(HERE, "..");
const OUTPUT_PATH = join(PROJECT_ROOT, "docs", "content", "reference", "module-reference.md");

// Escape `<`, `>`, `&` so Vue's template compiler does not misread prose/table
// text (e.g. a module arg description containing `BEGIN <id>`) as an HTML tag.
function esc(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\|/g, "\\|"); // literal pipe in a table cell would split the column
}

function renderArgs(args?: Record<string, { type: string; required: boolean; description: string }>): string {
  if (!args || Object.keys(args).length === 0) return "_(none)_";
  const rows = Object.entries(args)
    .map(([name, info]) => {
      const req = info.required ? "required" : "optional";
      return `| \`${name}\` | \`${esc(info.type)}\` | ${req} | ${esc(info.description)} |`;
    })
    .join("\n");
  return `| Arg | Type | Required | Description |\n| --- | --- | --- | --- |\n${rows}`;
}

function renderModule(m: {
  name: string;
  description: string;
  idempotent?: boolean;
  source?: string;
  args?: Record<string, { type: string; required: boolean; description: string }>;
  examples?: string[];
  notes?: string;
}): string {
  const parts: string[] = [];
  parts.push(`## ${m.name}`, "");
  parts.push(esc(m.description), "");
  const tags: string[] = [];
  if (m.idempotent) tags.push("idempotent");
  if (m.source) tags.push(`source: ${m.source}`);
  if (tags.length) parts.push(`_${tags.join(" · ")}_`, "");
  parts.push("**Args**", "", renderArgs(m.args), "");
  if (m.examples && m.examples.length > 0) {
    parts.push("**Examples**", "");
    for (const ex of m.examples) parts.push("```yaml", ex, "```", "");
  }
  if (m.notes && m.notes.length > 0) {
    parts.push("", `> ${esc(m.notes)}`, "");
  }
  return parts.join("\n");
}

async function main(): Promise<void> {
  // Populate the search-metadata map so searchModules() covers all 12 modules.
  registerAllModules();
  const modules = searchModules("");

  const banner =
    "<!-- AUTO-GENERATED by scripts/generate-module-reference.ts — do not edit by hand. -->";
  const intro =
    "# Module Reference\n\n" +
    "Every module RoleCall can dispatch in a task — either in Ansible-style collapsed form " +
    "(`copy: { dest }`) or explicitly (`module: copy` with `args:`). Listed programmatically " +
    "from the runtime `meta` (mirrors `rolecall docs modules`).\n";

  const body = modules.map(renderModule).join("\n");
  const contents = `${banner}\n\n${intro}\n${body}\n`;

  await Bun.write(OUTPUT_PATH, contents);
  console.log(
    `generate-module-reference wrote ${modules.length} module(s) -> ${relative(PROJECT_ROOT, OUTPUT_PATH)}`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
